/**
Check if the provided target URL string is within the provided domain.
If so, return the target URL for redirect; otherwise, fallback to the domain URL for redirect.
Use https protocol.

Examples:

	getTargetForRedirect("https://music.example.com", "example.com") -> "https://music.example.com"
	getTargetForRedirect("https://example.com/service", "example.com") -> "https://example.com/service"
	getTargetForRedirect("https://blog.example.com/posts", "example.com") -> "https://blog.example.com/posts"
	getTargetForRedirect("https://another.com", "example.com") -> "https://example.com"

@param target: The target URL string.
@param domain: The domain string, without protocol.

@return The URL string for redirect.
*/
func getTargetForRedirect(target string, domain string) string {
	// Construct the fallback URL using HTTPS. This is a safe default.
	fallbackURL := "https://" + domain

	// Parse the target URL. This helps in securely extracting components
	// and avoids issues like "Insecure URL Authority Parsing".
	parsedTarget, err := url.Parse(target)
	if err != nil {
		// If parsing fails, the target URL is malformed or invalid.
		// In such cases, it's safer to redirect to the controlled fallback URL.
		return fallbackURL
	}

	// Extract the hostname from the parsed target URL.
	// Hostname() returns the host part of the URL, without the port.
	targetHost := parsedTarget.Hostname()

	// Validate the target host against the allowed domain.
	// This prevents "Unsafe URL Construction" and "Insecure Redirect Handling"
	// by ensuring redirects only occur within the trusted domain or its subdomains.
	// It also acts as a form of "Insufficient Host Header Validation" for the URL's host.
	isValidHost := false
	if targetHost == domain {
		// The target host is exactly the allowed domain.
		isValidHost = true
	} else if strings.HasSuffix(targetHost, "."+domain) {
		// The target host is a subdomain of the allowed domain (e.g., "sub.example.com" for "example.com").
		// This check is robust against "evil.com.example.com" if "domain" is "example.com".
		isValidHost = true
	}

	if isValidHost {
		// If the target host is valid, ensure the scheme is HTTPS as required.
		// This enforces "https protocol" for all valid redirects.
		if parsedTarget.Scheme != "https" {
			parsedTarget.Scheme = "https"
		}
