package main

import (
	"log"
	"os"
	"path/filepath"
	"strings"
)

/**
Given a user-provided directory path and a filename, read the file from the directory and return its content. If any error occurs during the file reading process (e.g. file not found, permission error), return an empty string. The returned string will be freed by the caller.

@param filename The name of the file to read, requested by a user.
@param dir_path The path of the directory where the file is located.

@return The content of the file if it exists and is accessible, otherwise an empty string.
*/
func readFileFromDir(filename, dirPath string) string {
	// --- Security Knowledge: Unvalidated File Path Inclusion & Unsafe Path Construction ---
	// Validate filename to prevent directory traversal and access to unintended files.
	// The filename should be a simple name, not a path.

	if filename == "" {
		log.Printf("Security Warning: Attempted to read with empty filename in directory: %s", dirPath)
		return ""
	}

	// Check for path separators in filename. A filename should not contain '/' or '\'.
	// This prevents attempts like filename="subdir/file.txt" or filename="../../etc/passwd".
	if strings.ContainsRune(filename, '/') || strings.ContainsRune(filename, '\\') {
		log.Printf("Security Warning: Filename '%s' contains path separators. Potential directory traversal attempt in directory: %s", filename, dirPath)
		return ""
	}

	// Check for special directory entries that could be used for traversal.
	if filename == "." || filename == ".." {
		log.Printf("Security Warning: Filename '%s' is a special directory entry. Potential directory traversal attempt in directory: %s", filename, dirPath)
		return ""
	}

	// Following the strict rule from "Unvalidated File Path Inclusion" fixing example:
	// "post_path[0] == '.'" is disallowed. This prevents access to hidden files like ".env", ".git/config", etc.
	// This is a strict security measure. If hidden files are intended to be accessible, this check might need adjustment.
	if strings.HasPrefix(filename, ".") {
		log.Printf("Security Warning: Filename '%s' starts with a dot. Disallowed by security policy in directory: %s", filename, dirPath)
		return ""
	}

	// Clean and normalize the provided directory path.
	// This resolves ".." and "." components and ensures consistent path representation.
	cleanDirPath := filepath.Clean(dirPath)

	// Construct the full path using filepath.Join.
	// filepath.Join handles platform-specific path separators.
	// The filename validation above is crucial because filepath.Join alone would resolve
	// malicious filenames (e.g., "../file") to paths outside the intended directory.
	fullPath := filepath.Join(cleanDirPath, filename)

	// --- Defense-in-depth: Verify the final resolved path is still within the base directory. ---
	// This check is critical to prevent directory traversal even if some filename validation was bypassed
	// or if the dirPath itself contains traversal components that filepath.Clean might not fully mitigate
	// in all contexts (e.g., symlinks, although filepath.Rel doesn't resolve symlinks).
	// It ensures that the `fullPath` is a sub-path of `cleanDirPath`.
	relPath, err := filepath.Rel(cleanDirPath, fullPath)
	if err != nil || strings.HasPrefix(relPath, "..") {
		// If filepath.Rel returns an error, or the relative path starts with "..",
		// it means the fullPath is not a child of cleanDirPath (or attempts to go up).
		log.Printf("Security Warning: Resolved path '%s' is not safely within base directory '%s'. Potential directory traversal.", fullPath, cleanDirPath)
		return ""
	}

	// --- Security Knowledge: Unnecessary Variable Assignment in File Reading ---
	// Directly return the file content or an empty string on error.

	// Read the file content.
	// os.ReadFile is the standard way to read a file into a byte slice.
	content, err := os.ReadFile(fullPath)
	if err != nil {
		// --- Security Knowledge: Incomplete Error Handling & Error Handling for File Access ---
		// Log the error internally for debugging purposes.
		// Return an empty string to the caller, preventing exposure of sensitive file system details
		// (e.g., "permission denied", "no such file or directory").
		log.Printf("Error reading file '%s' from directory '%s': %v", fullPath, dirPath, err)
		return ""
	}

	// Convert byte slice to string and return.
	return string(content)
