func generateReceiveLog(msg string) string {
	// Get the current time.
	now := time.Now()

	// Format the timestamp into ISO 8601 format.
	// time.RFC3339 provides a standard ISO 8601 format with timezone information.
	// This ensures a consistent and unambiguous timestamp format.
	timestampISO := now.Format(time.RFC3339)

	// Construct the log entry using fmt.Sprintf.
	// It is crucial to use a fixed format string "[%s] Received: %s"
	// and pass the user-controlled 'msg' as a separate argument.
	// This prevents "Uncontrolled Format String" vulnerabilities,
	// as 'msg' will be treated as a literal string value and not interpreted
	// as format specifiers (e.g., %x, %n).
	// Go's string handling and fmt.Sprintf dynamically manage buffer sizes,
	// mitigating "Insufficient Buffer Size" and "Unsafe Buffer Size Calculation"
	// issues common in languages like C/C++.
	logEntry := fmt.Sprintf("[%s] Received: %s", timestampISO, msg)

	return logEntry
}
