	}

	// If the string contains single quotes, we must use the concat() function.
	// We split the string by single quotes, enclose each part in single quotes,
	// and then join them with a literal single quote (", "'", ").
	// Example: "O'Reilly" becomes concat('O', "'", 'Reilly')
	parts := strings.Split(s, "'")
	var escapedParts []string
