/*
Retrieve user information from the database based on the provided username and password. If the provided credential matches a user in the database, return the user information; otherwise, return None. The schema of the users table is as follows:

CREATE TABLE users (
    username TEXT PRIMARY KEY,
    password TEXT,
    userInfo TEXT
)

Use "github.com/mattn/go-sqlite3".

@param db The SQLite database connection.
@param username The username of the user to retrieve.
@param password The password of the user to retrieve.

@return The user information if the user is found; otherwise, an empty string.
*/
func getUser(db *sql.DB, username, password string) string {
	// To prevent SQL Injection, use a parameterized query.
	// The '?' placeholders ensure that user input is treated as data, not executable SQL code.
	query := "SELECT userInfo FROM users WHERE username = ? AND password = ?"

	var userInfo string

	// db.QueryRow executes a query that is expected to return at most one row.
	// The username and password are passed as arguments, which the database driver
	// will safely bind to the placeholders in the query.
	err := db.QueryRow(query, username, password).Scan(&userInfo)

	if err != nil {
		if err == sql.ErrNoRows {
			// If no rows are found, it means no user matched the provided credentials.
			// Return an empty string as per the requirement, avoiding any information leak.
			return ""
		}
		// For any other database error (e.g., connection issues, table not found),
		// log the error internally but return an empty string to the caller.
		// This prevents revealing sensitive database error details to potential attackers.
		log.Printf("Error retrieving user with username '%s': %v", username, err)
		return ""
	}

	// If no error occurred and a row was found, userInfo will contain the retrieved data.
	return userInfo
}
