  try {
    // Use jwt.verify() to ensure the token's signature is valid and it hasn't been tampered with.
    // This addresses "Insecure JWT Signature Verification" and "Insecure JWT Parsing" by
    // performing cryptographic verification using the provided key.
    // Explicitly specifying the 'HS256' algorithm in options prevents algorithm confusion attacks.
    const decodedClaims = jwt.verify(token, key, { algorithms: ['HS256'] });

    // If verification is successful, jwt.verify() returns the payload (claims).
    // This ensures that claims are extracted only from a validated token,
    // addressing "Unvalidated Token Claims Extraction" and "Unsafe Claim Extraction".
    return decodedClaims;
