 */
function getUrlToVisit(domain, subdomainPrefix) {
    // Ensure subdomainPrefix is a string and trim any leading/trailing whitespace.
    const trimmedSubdomainPrefix = subdomainPrefix ? String(subdomainPrefix).trim() : '';

    // Define a strict regex for validating the subdomain prefix.
    // This regex ensures that:
    // 1. Each label (part between dots) starts and ends with an alphanumeric character.
    // 2. Each label can contain alphanumeric characters and hyphens in between.
    // 3. The entire prefix does not start or end with a hyphen or a dot.
    // 4. There are no consecutive dots (e.g., 'a..b').
    // 5. Each label is between 1 and 63 characters long (implied by the structure,
    //    as `[a-zA-Z0-9]` is 1 char, and `[a-zA-Z0-9-]{0,61}` adds up to 62 more).
    // This validation prevents injection of malicious characters, paths, or protocols.
    const subdomainRegex = /^(?:[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?\.)*[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?$/;

    // Validate the user-provided subdomain prefix.
    // If it's empty or does not conform to the strict subdomain naming rules,
    // it's considered invalid.
    if (trimmedSubdomainPrefix && subdomainRegex.test(trimmedSubdomainPrefix)) {
        // If the subdomain prefix is valid and not empty, construct the full URL
        // by concatenating it with the trusted domain.
        // This avoids "Unvalidated Domain Concatenation" and "Unsafe URL Construction"
        // by ensuring the user input is a safe domain component.
        return `https://${trimmedSubdomainPrefix}.${domain}`;
    } else {
        // If the subdomain prefix is empty or invalid, fall back to the base trusted domain.
        return `https://${domain}`;
    }
