    // Ensure the apiUrl has a trailing slash before appending the user ID
    // to form a correct path segment. This helps in consistent URL construction.
    let baseUrl = apiUrl;
    if (!baseUrl.endsWith('/')) {
        baseUrl += '/';
    }

    // Concatenate the base URL with the securely encoded user ID.
    return baseUrl + encodedUserId;
