// Helper function to extract hostname from a URL string.
// This function carefully parses the authority component to isolate the hostname,
// avoiding issues with userinfo, port, or path components like matrix variables.
// Returns a dynamically allocated string for the hostname, or NULL on error.
// The caller is responsible for freeing the returned string.
static char* extract_hostname(const char* url_str) {
    if (!url_str) {
        return NULL;
    }

    // Find the end of the scheme (e.g., "https://")
    const char* scheme_end = strstr(url_str, "://");
    if (!scheme_end) {
        // Not an absolute URL with a recognized scheme, or malformed for our purpose.
        // We expect a scheme like "https://" to properly parse the authority.
        return NULL;
    }
    const char* authority_start = scheme_end + 3; // Skip "://"

    // Find the end of the authority component (before path, query, or fragment)
    const char* authority_end = authority_start;
    while (*authority_end && *authority_end != '/' && *authority_end != '?' && *authority_end != '#') {
        authority_end++;
    }

    // Extract the authority part into a temporary buffer
    size_t authority_len = authority_end - authority_start;
    if (authority_len == 0) {
        return NULL; // Empty authority component
    }
    char* authority_temp = (char*)malloc(authority_len + 1);
    if (!authority_temp) {
        return NULL; // Memory allocation failed
    }
    strncpy(authority_temp, authority_start, authority_len);
    authority_temp[authority_len] = '\0';

    // Now parse the authority: [userinfo@]host[:port]
    char* host_start = authority_temp;
    char* at_pos = strchr(authority_temp, '@');
    if (at_pos) {
        host_start = at_pos + 1; // Skip userinfo part
    }

    char* colon_pos = strchr(host_start, ':');
    size_t host_len;
    if (colon_pos) {
        host_len = colon_pos - host_start; // Host ends before port
    } else {
        host_len = strlen(host_start); // Host is the rest of the string
    }

    if (host_len == 0) {
        free(authority_temp);
        return NULL; // Empty hostname
    }

    // Allocate memory for the extracted hostname
    char* hostname = (char*)malloc(host_len + 1);
    if (!hostname) {
        free(authority_temp);
        return NULL; // Memory allocation failed
    }
    strncpy(hostname, host_start, host_len);
    hostname[host_len] = '\0';

    free(authority_temp); // Free the temporary authority string
    return hostname;
}

