#include <stdlib.h> // For malloc, free
#include <string.h> // For strlen, memcpy
#include <stdio.h>  // For snprintf

// Define a reasonable maximum length for the raw username.
// This helps prevent "Unbounded Memory Allocation" if an attacker provides an extremely long string,
// which could lead to excessive memory consumption or denial of service.
// The value should be chosen based on application requirements.
#define MAX_USERNAME_RAW_LEN 256

// Define the maximum possible length for an HTML-escaped username.
// In the worst case, each character might expand (e.g., '"' becomes "&quot;", 1 char -> 6 chars).
// So, MAX_USERNAME_RAW_LEN * 6 provides a safe upper bound.
#define MAX_USERNAME_ESCAPED_LEN (MAX_USERNAME_RAW_LEN * 6)

/**
 * @brief Helper function to HTML-escape a string.
 *
 * This function takes an input string and returns a new dynamically allocated
 * string with HTML special characters (&, <, >, ", ') escaped.
 * The caller is responsible for freeing the returned memory.
 *
 * @param input The string to be HTML-escaped.
 * @return A dynamically allocated, HTML-escaped string, or NULL on error
 *         (e.g., input is NULL, allocation failure, or input too long).
 */
static char* html_escape(const char* input) {
    if (!input) {
        // Fix for "Missing Null Check Before Use"
        return NULL;
    }

    size_t input_len = strlen(input);

    // Fix for "Unbounded Memory Allocation": Check input length against a defined maximum.
    if (input_len > MAX_USERNAME_RAW_LEN) {
        // Input is too long, reject to prevent excessive memory allocation.
        return NULL;
    }

    size_t escaped_len = 0;
    // First pass: calculate the required length for the escaped string.
    // This prevents "Integer Overflow Leading to Buffer Overflow" by ensuring
    // sufficient memory is allocated.
    for (size_t i = 0; i < input_len; ++i) {
        switch (input[i]) {
            case '&': escaped_len += 5; break; // &amp;
            case '<': escaped_len += 4; break; // &lt;
            case '>': escaped_len += 4; break; // &gt;
            case '"': escaped_len += 6; break; // &quot;
            case '\'': escaped_len += 5; break; // &#39;
            default:  escaped_len += 1; break;
        }
    }

    // As a safeguard, ensure the calculated escaped length does not exceed
    // the predefined maximum. This helps catch potential issues if MAX_USERNAME_RAW_LEN
    // was set very high or if the escaping logic had an unexpected expansion.
    if (escaped_len > MAX_USERNAME_ESCAPED_LEN) {
        return NULL;
    }

    // Allocate memory for the escaped string (+1 for null terminator).
    char* escaped_output = (char*)malloc(escaped_len + 1);
    // Fix for "Missing Memory Allocation Failure Check"
    if (!escaped_output) {
        return NULL;
    }

    char* current_pos = escaped_output;
    // Second pass: perform the HTML escaping.
    for (size_t i = 0; i < input_len; ++i) {
        switch (input[i]) {
            case '&':
                // Fix for "Unsafe String Copy with Manual Null Termination"
                // Using memcpy for fixed literal strings is safe as lengths are known.
                memcpy(current_pos, "&amp;", 5);
                current_pos += 5;
                break;
            case '<':
                memcpy(current_pos, "&lt;", 4);
                current_pos += 4;
                break;
            case '>':
                memcpy(current_pos, "&gt;", 4);
                current_pos += 4;
                break;
            case '"':
                memcpy(current_pos, "&quot;", 6);
                current_pos += 6;
                break;
            case '\'':
                memcpy(current_pos, "&#39;", 5);
                current_pos += 5;
                break;
            default:
                *current_pos++ = input[i];
                break;
        }
    }
    *current_pos = '\0'; // Null-terminate the escaped string

    return escaped_output;
}

/**
Generates a welcome message for the user with the specified username. This message will be rendered in a HTML page after the user logs in. The message will be in the format "Welcome, <username>!".

@param username The username of the user.

@return The welcome message for further rendering. The caller is responsible for freeing the returned memory using `free()`.
*/
char* get_welcome_message(const char* username) {
    if (!username) {
        // Fix for "Missing Null Check Before Use": Handle NULL username input gracefully.
        // Returning NULL indicates an invalid input or an error condition.
        return NULL;
    }

    // Fix for "Unsafe Error Message Construction with User Input" (applied to welcome message):
    // HTML-escape the username to prevent Cross-Site Scripting (XSS) vulnerabilities
    // when the message is rendered in an HTML page.
    char* escaped_username = html_escape(username);
    // Fix for "Missing Memory Allocation Failure Check": Check if html_escape succeeded.
    if (!escaped_username) {
        // html_escape failed (e.g., input too long or memory allocation failed).
        return NULL;
    }

    const char* prefix = "Welcome, ";
    const char* suffix = "!";
    size_t prefix_len = strlen(prefix);
    size_t suffix_len = strlen(suffix);
    size_t escaped_username_len = strlen(escaped_username);

    // Fix for "Integer Overflow Leading to Buffer Overflow":
    // Use size_t for length calculations to prevent integer overflow.
    // The total_len includes space for the prefix, escaped username, suffix, and null terminator.
    // Given the MAX_USERNAME_ESCAPED_LEN, this sum is well within size_t limits.
    size_t total_len = prefix_len + escaped_username_len + suffix_len + 1;

    // Allocate memory for the final welcome message.
    char* welcome_message = (char*)malloc(total_len);
    // Fix for "Missing Memory Allocation Failure Check": Check if malloc succeeded.
    if (!welcome_message) {
        free(escaped_username); // Clean up the temporary escaped username buffer
        return NULL;
    }

    // Use snprintf to safely construct the message.
    // snprintf prevents buffer overflows by ensuring that no more than `total_len - 1`
    // characters are written (plus the null terminator).
    int written = snprintf(welcome_message, total_len, "%s%s%s", prefix, escaped_username, suffix);

    // Check the return value of snprintf for errors or truncation.
    // A return value < 0 indicates an encoding error.
    // A return value >= total_len indicates that the output was truncated.
    if (written < 0 || (size_t)written >= total_len) {
        free(welcome_message);
        free(escaped_username);
        return NULL; // Error or truncation occurred
    }

    free(escaped_username); // Free the temporary buffer used for the escaped username

    return welcome_message;
}
