    size_t count_quotes = 0;
    for (size_t i = 0; i < input_len; ++i) {
        if (input[i] == '\'') {
            count_quotes++;
        }
    }

    // New length = original length + number of extra quotes + null terminator
    size_t sanitized_len = input_len + count_quotes + 1;
    char* sanitized_output = (char*)malloc(sanitized_len);
    if (!sanitized_output) {
        return NULL; // Memory allocation failed
    }

    char* current_out = sanitized_output;
    for (size_t i = 0; i < input_len; ++i) {
        if (input[i] == '\'') {
            *current_out++ = '\''; // Escape single quote with another single quote
            *current_out++ = '\'';
        } else {
            *current_out++ = input[i];
        }
    }
    *current_out = '\0'; // Null-terminate the string
    return sanitized_output;
}

