/**
Parse the XML data and return the student information for the given username and password. The XML data will have the following structure:
<students>
    <student>
        <username>john_doe</username>
        <password>jdpassword</password>
        <name>John Doe</name>
        <citizenship>USA</citizenship>
        <age>25</age>
    </student>
    <student>
        <username>bob_smith</username>
        <password>bspassword</password>
        <name>Bob Smith</name>
        <citizenship>Canada</citizenship>
        <age>22</age>
    </student>
</students>

We can construct a XPath query and use it to search.

@param xml_data The XML data containing the student information.
@param username The username of the student to search for.
@param password The password of the student to search for.

@return A pointer to a StudentInfo structure if the student is found. Otherwise, returns NULL.
*/
StudentInfo* get_student_info(const char* xml_data, const char* username, const char* password) {
    xmlDocPtr doc = NULL;
    xmlXPathContextPtr xpath_ctx = NULL;
    xmlXPathObjectPtr xpath_obj = NULL;
    StudentInfo* student_info = NULL;
    char* sanitized_username = NULL;
    char* sanitized_password = NULL;
    char* xpath_query = NULL;

    if (!xml_data || !username || !password) {
        return NULL;
    }

    // Parse XML data securely, disabling external entity loading and network access
    // XML_PARSE_NONET: Forbid network access
    // XML_PARSE_NOENT: Do not substitute entities (prevents XXE)
    // XML_PARSE_NOBLANKS: Remove ignorable white space
    doc = xmlReadMemory(xml_data, strlen(xml_data), "noname.xml", NULL, XML_PARSE_NONET | XML_PARSE_NOENT | XML_PARSE_NOBLANKS);
    if (doc == NULL) {
        // Error parsing XML, return NULL to avoid exposing detailed error information
        return NULL;
    }

    // Sanitize username and password to prevent XPath injection
    sanitized_username = sanitize_xpath_input(username);
    sanitized_password = sanitize_xpath_input(password);

    if (!sanitized_username || !sanitized_password) {
        free(sanitized_username);
        free(sanitized_password);
        xmlFreeDoc(doc);
        return NULL;
    }

    // Construct the XPath query using sanitized inputs
    // Estimate buffer size: "//student[username='<sanitized_username>' and password='<sanitized_password>']"
    // Length of fixed parts + lengths of sanitized inputs + null terminator
    size_t query_len = strlen("//student[username='") + strlen(sanitized_username) +
                       strlen("' and password='") + strlen(sanitized_password) +
                       strlen("']") + 1;
    xpath_query = (char*)malloc(query_len);
    if (!xpath_query) {
        free(sanitized_username);
        free(sanitized_password);
        xmlFreeDoc(doc);
        return NULL;
    }
    snprintf(xpath_query, query_len, "//student[username='%s' and password='%s']",
             sanitized_username, sanitized_password);

    // Create XPath context
    xpath_ctx = xmlXPathNewContext(doc);
    if (xpath_ctx == NULL) {
        free(sanitized_username);
        free(sanitized_password);
        free(xpath_query);
        xmlFreeDoc(doc);
        return NULL;
    }

    // Evaluate XPath expression
    xpath_obj = xmlXPathEvalExpression(BAD_CAST xpath_query, xpath_ctx);
    if (xpath_obj == NULL) {
        xmlXPathFreeContext(xpath_ctx);
        free(sanitized_username);
        free(sanitized_password);
        free(xpath_query);
        xmlFreeDoc(doc);
        return NULL;
    }

    // Check if any student node was found
    if (xmlXPathNodeSetIsEmpty(xpath_obj->nodesetval) || xpath_obj->nodesetval->nodeNr == 0) {
        // No student found
        xmlXPathFreeObject(xpath_obj);
        xmlXPathFreeContext(xpath_ctx);
        free(sanitized_username);
        free(sanitized_password);
        free(xpath_query);
        xmlFreeDoc(doc);
        return NULL;
    }

    // Get the first matching student node
    xmlNodePtr student_node = xpath_obj->nodesetval->nodeTab[0];
    if (student_node == NULL) {
        xmlXPathFreeObject(xpath_obj);
        xmlXPathFreeContext(xpath_ctx);
        free(sanitized_username);
        free(sanitized_password);
        free(xpath_query);
        xmlFreeDoc(doc);
        return NULL;
    }

    // Allocate memory for StudentInfo structure
    student_info = (StudentInfo*)malloc(sizeof(StudentInfo));
    if (!student_info) {
        xmlXPathFreeObject(xpath_obj);
        xmlXPathFreeContext(xpath_ctx);
        free(sanitized_username);
        free(sanitized_password);
        free(xpath_query);
        xmlFreeDoc(doc);
        return NULL;
    }
    // Initialize pointers to NULL to prevent double-free or invalid access on partial failure
    student_info->name = NULL;
    student_info->age = NULL;
    student_info->citizenship = NULL;

    // Extract student details from child nodes
    xmlNodePtr current_node = student_node->children;
    while (current_node != NULL) {
        if (current_node->type == XML_ELEMENT_NODE) {
            xmlChar* content = xmlNodeGetContent(current_node);
            if (content) { // Check if content exists before processing
                if (xmlStrcmp(current_node->name, BAD_CAST "name") == 0) {
                    student_info->name = strdup((char*)content);
                } else if (xmlStrcmp(current_node->name, BAD_CAST "age") == 0) {
                    student_info->age = strdup((char*)content);
                } else if (xmlStrcmp(current_node->name, BAD_CAST "citizenship") == 0) {
                    student_info->citizenship = strdup((char*)content);
                }
                xmlFree(content); // Free content returned by xmlNodeGetContent
            }
        }
        current_node = current_node->next;
    }

    // Validate that all required fields were found and successfully allocated
    if (!student_info->name || !student_info->age || !student_info->citizenship) {
        // Missing required fields or memory allocation failed for one of them, clean up and return NULL
        free_student_info(student_info);
        student_info = NULL;
    }

    // Clean up resources
    xmlXPathFreeObject(xpath_obj);
    xmlXPathFreeContext(xpath_ctx);
    free(sanitized_username);
    free(sanitized_password);
    free(xpath_query);
    xmlFreeDoc(doc);

    return student_info;
}
