std::string read_file_from_dir(const std::string &filename, const std::string &dir_path) {
    // 1. Construct the full file path
    std::filesystem::path base_path(dir_path);
    std::filesystem::path combined_path = base_path / filename;

    // 2. Validate the path to prevent Path Traversal
    // This step is crucial to ensure that the user cannot access files outside
    // the intended directory by manipulating 'filename' (e.g., using "../").
    std::filesystem::path canonical_base_path;
    std::filesystem::path canonical_file_path;

    try {
        // Get canonical path for the base directory.
        // This resolves all symlinks, '..', and '.' components.
        // It will throw std::filesystem::filesystem_error if dir_path does not exist or is not accessible.
        canonical_base_path = std::filesystem::canonical(base_path);

        // Get canonical path for the combined file path.
        // This resolves the full path to the target file.
        // It will throw std::filesystem::filesystem_error if the file does not exist or is not accessible.
        canonical_file_path = std::filesystem::canonical(combined_path);
    } catch (const std::filesystem::filesystem_error& e) {
        // If canonicalization fails (e.g., path doesn't exist, permission denied,
        // or an invalid path component), it's considered an error or a traversal attempt.
        // Return an empty string as per the function's error handling requirement.
