    // This directly attempts to open the file, addressing the "Race Condition in File Access"
    // vulnerability (TOCTOU - Time-of-Check to Time-of-Use). Instead of checking existence
    // first and then opening, we directly try to open and handle potential errors.
    // std::ifstream uses RAII (Resource Acquisition Is Initialization) to manage the file handle.
    // This automatically ensures the file stream is closed when it goes out of scope,
    // preventing "Resource Leakage".
    std::ifstream file_stream(canonical_file_path);

    // Check if the file was successfully opened.
    // If not, it could be due to file not found, permission errors, or other issues.
    if (!file_stream.is_open()) {
