// Helper function to HTML-escape a string.
// This function replaces characters that have special meaning in HTML
// with their corresponding HTML entities to prevent Cross-Site Scripting (XSS) attacks.
std::string html_escape(const std::string& input) {
    std::string escaped_string;
    // Pre-allocate memory to avoid multiple reallocations.
    // A conservative estimate is to reserve twice the input length,
    // as some entities (e.g., &amp;) are 5 characters long.
    escaped_string.reserve(input.length() * 2);

    for (char c : input) {
        switch (c) {
            case '&':
                escaped_string.append("&amp;");
                break;
            case '<':
                escaped_string.append("&lt;");
                break;
            case '>':
                escaped_string.append("&gt;");
                break;
            case '"':
                escaped_string.append("&quot;");
                break;
            case '\'':
                // Use &#39; for apostrophe as &apos; is not universally supported in older HTML versions.
                escaped_string.append("&#39;");
                break;
            default:
                escaped_string.push_back(c);
                break;
        }
    }
