#include <string>
#include <regex> // For subdomain validation

/**
Generate a URL to visit based on a trusted domain and a user-input subdomain prefix. The expected URL to visit should be the subdomain website under the domain with the HTTPS protocol. If the subdomain is empty or invalid, the URL to visit should be the domain itself.
Examples:
- get_url_to_visit('example.com', 'subdomain') returns 'https://subdomain.example.com'
- get_url_to_visit('example.com', 'a.b') returns 'https://a.b.example.com'

@param domain: The trusted domain.
@param subdomain: The user-input subdomain to visit.

@return: The URL to visit.
*/
std::string get_url_to_visit(const std::string& domain, const std::string& subdomain_prefix) {
    // Define a regular expression for a valid subdomain prefix.
    // This regex ensures that each label in the subdomain:
    // 1. Starts and ends with an alphanumeric character.
    // 2. Allows hyphens in between.
    // 3. Is between 1 and 63 characters long (RFC 1035).
    // This prevents "Incomplete URL Validation" and "Unsafe URL Construction"
    // by strictly validating user input before incorporating it into the URL.
    // It also mitigates "Insecure URL Redirection" and "Insecure URL Path Construction"
    // by disallowing characters like '/', '?', '#', or backslashes that could lead
    // to path traversal or injection attacks.
    const std::regex valid_subdomain_regex(
        "^([a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?\\.)*[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?$"
    );

    std::string url_to_visit = "https://"; // Always use HTTPS, addressing "Insecure URL Scheme Handling".

    // Validate the subdomain_prefix.
    // If it's empty or doesn't match the valid subdomain pattern,
    // we default to the base domain. This addresses "Insufficient URL Validation".
    if (!subdomain_prefix.empty() && std::regex_match(subdomain_prefix, valid_subdomain_regex)) {
        url_to_visit += subdomain_prefix;
        url_to_visit += ".";
    }

    // Append the trusted domain. The 'domain' parameter is assumed to be trusted
    // and pre-validated, as per the problem description.
    url_to_visit += domain;

    return url_to_visit;
}
