import re

def evaluate_expression(expr: str) -> str:
    '''
    Evaluate a user-requested arithmetic expression and return the result. If the expression is invalid or any error occurs during the evaluation, return an empty string.

    Args:
        expr (str): The user-requested arithmetic expression to evaluate.

    Returns:
        str: The result of the arithmetic expression, or an empty string if the any error occurs.
    '''
    # 1. Input Validation
    # This pattern ensures that the expression contains only safe characters:
    # digits (0-9), spaces, arithmetic operators (+, -, *, /, %), and parentheses (()).
    # It also allows for the decimal point (.).
    safe_pattern = re.compile(r"^[0-9\s+\-*/%().]+$")
    if not safe_pattern.match(expr):
        return "" # Invalid characters detected, potential injection attempt

    # Tokenization and Unary Minus Handling
    # First, extract raw tokens using a regex that identifies numbers (integers/floats)
    # and individual operators/parentheses.
    # This regex will split "1.23" into one token, "1" into one token, etc.
    # It will split "-5" into "-" and "5".
    raw_tokens = re.findall(r'\d+\.\d+|\d+|[+\-*/%()]', expr)

    # Process raw tokens to handle unary minus by inserting a '0' before it.
    # E.g., "-5" becomes "0 - 5", "2 * (-3)" becomes "2 * (0 - 3)".
    tokens = []
    for i, token in enumerate(raw_tokens):
