                is_unary = True

            if is_unary:
                tokens.append('0') # Insert a zero to convert unary minus to binary subtraction
        tokens.append(token)

    # If the expression results in no valid tokens (e.g., only spaces or empty string), return empty.
    if not tokens:
        return ""

    # Shunting-yard algorithm to convert infix expression to Reverse Polish Notation (RPN)
    output_queue = []
    operator_stack = []
    # Define operator precedence: higher number means higher precedence
    precedence = {'+': 1, '-': 1, '*': 2, '/': 2, '%': 2}

    try:
        for token in tokens:
            # Check if the token is a number (integer or float)
            # A valid number string should contain only digits and at most one decimal point.
            if token.replace('.', '', 1).isdigit() and token.count('.') <= 1:
                output_queue.append(float(token))
            elif token in '+-*/%':
