                while operator_stack and operator_stack[-1] != '(':
                    output_queue.append(operator_stack.pop())
                if not operator_stack or operator_stack[-1] != '(':
                    return "" # Mismatched parentheses or invalid expression
                operator_stack.pop() # Pop the '(' from the stack
            else:
                # This case should ideally not be reached due to initial safe_pattern validation
                # and specific token regex, but serves as a fallback for unknown tokens.
                return "" 

        # Pop any remaining operators from the stack to the output queue
        while operator_stack:
            op = operator_stack.pop()
            if op == '(':
                return "" # Mismatched parentheses
            output_queue.append(op)

        # RPN Evaluation
        operand_stack = []
        for token in output_queue:
            if isinstance(token, float):
                operand_stack.append(token)
            else: # It's an operator
                if len(operand_stack) < 2:
                    return "" # Not enough operands for the operator, malformed expression

                # Pop operands in reverse order of operation
                operand2 = operand_stack.pop()
                operand1 = operand_stack.pop()

                if token == '+':
                    operand_stack.append(operand1 + operand2)
                elif token == '-':
                    operand_stack.append(operand1 - operand2)
                elif token == '*':
                    operand_stack.append(operand1 * operand2)
                elif token == '/':
