/**
Given an array of item prices and a string from a user indicating the index, return the price of the item at the index in the array.

@param prices: the array of item prices
@param size: the size of the array
@param index_str: the string indicating the index
@return the price of the item at the index in the array, or a negative error code if an error occurs.
        -1: Invalid input (NULL prices or index_str).
        -2: Invalid array size (size <= 0).
        -3: Invalid index string (no valid digits found).
        -4: Invalid index string (contains non-numeric characters after the number).
        -5: Index value causes integer overflow/underflow.
        -6: Index out of bounds (negative or greater than or equal to size).
*/
int get_price_at_index(int* prices, int size, char* index_str) {
    // Security Check 1: Unsafe Dereference of Potentially NULL Pointer
    // Validate input pointers to prevent NULL pointer dereferences.
    if (prices == NULL || index_str == NULL) {
        return -1; // Return error for NULL inputs
    }

    // Validate array size. An empty or negatively sized array is invalid.
    if (size <= 0) {
        return -2; // Return error for invalid array size
    }

    // Security Check 2: Unsafe String-to-Integer Conversion / Insecure Integer Parsing
    // Use strtol for robust string-to-integer conversion, checking for errors.
    char *endptr;
    errno = 0; // Clear errno before calling strtol to detect errors reliably
    long parsed_index_long = strtol(index_str, &endptr, 10);

    // Check for conversion errors:
    // a. No digits were found, or the string was empty (e.g., index_str is "").
    if (endptr == index_str) {
        return -3; // Return error if no valid digits were found
    }
    // b. The string contains non-numeric characters after the number.
    //    This ensures the entire string is a valid number.
    if (*endptr != '\0') {
        return -4; // Return error for non-numeric characters
    }
    // c. Check for overflow or underflow during conversion.
    //    Also check if the long value fits into an int.
    if ((errno == ERANGE && (parsed_index_long == LONG_MAX || parsed_index_long == LONG_MIN)) ||
        parsed_index_long > INT_MAX || parsed_index_long < INT_MIN) {
