    // Using 'size_t' for string length is safer than 'int' to prevent potential
    // integer overflow issues with very long strings, as 'size_t' is guaranteed
    // to be able to hold the maximum size of an object.
    size_t len = strlen(str);

    // If the string is empty, there are no trailing spaces to remove.
    if (len == 0) {
        return;
    }

    // Initialize an index 'i' to point to the last character of the string.
    // Using a signed type (long) for 'i' allows it to safely go below zero
    // if the entire string consists of spaces, preventing underflow issues
    // that could occur with an unsigned type like size_t.
    long i = (long)len - 1;

